(async () => { 
    const res = await window.api.story.importScript(window.__demoId, "## 1. Pagi di Pasar\nAlur: Sari membuka lapaknya saat matahari terbit.\nNarasi: Pagi itu Sari membuka lapaknya saat matahari baru terbit di pasar.\n## 2. Pelanggan Pertama\nAlur: Seorang pembeli datang dan menawar dagangan Sari.\nNarasi: Pelanggan pertama datang dan menawar dagangan Sari dengan ramah.\n## 3. Pulang\nAlur: Sari pulang membawa uang dan senyum.\nNarasi: Sore harinya Sari pulang membawa uang dan senyum lebar.");
    const b = await window.api.projects.get(window.__demoId);
    const est = (n) => Math.round(Math.min(15, Math.max(3, n / 2.6 + 0.6)) * 1000);
    const words = (s) => s.trim().split(/\s+/).filter(Boolean).length;
    const expMs = b.clips.reduce((t, c) => t + est(words(c.narration)), 0);
    const ok = res.imported === 3 && res.skipped.length === 0 && b.clips.length === 3
      && b.clips[0].title === 'Pagi di Pasar' && b.clips[1].title === 'Pelanggan Pertama' && b.clips[2].title === 'Pulang'
      && b.clips[0].story.includes('membuka lapaknya') && b.clips[0].narration.includes('Pagi itu Sari')
      && b.project.durationSec === Math.max(10, Math.round(expMs / 1000));
    console.log('IMPOR-A ' + (ok ? 'LULUS' : 'GAGAL') + ' imported=' + res.imported + ' skipped=' + JSON.stringify(res.skipped)
      + ' durationSec=' + b.project.durationSec + ' expMs=' + expMs + ' titles=' + JSON.stringify(b.clips.map((c) => c.title)));
   })()

