    let err = '';
    try { await window.api.story.importScript(window.__demoId, 'Hanya teks biasa tanpa adegan.'); } catch (e) { err = e.message || String(e); }
    const after = await window.api.projects.get(window.__demoId);
    const ok = err.includes('tidak ada adegan') && after.clips.length === before.clips.length
      && after.clips[0].title === before.clips[0].title && after.project.title === before.project.title;
    console.log('IMPOR-D ' + (ok ? 'LULUS' : 'GAGAL') + ' err=' + err + ' clipsBefore=' + before.clips.length + ' clipsAfter=' + after.clips.length);
   })()

